const TB_SYM = new Map(TB_SYMBOLS.map(s => [s.id, s]));
function tbSymSVG(id, size = 20) { const s = TB_SYM.get(id); return s ? `<svg viewBox="0 0 64 64" width="${size}" height="${size}" class="tbsym"><title>${esc(s.en)}</title>${s.svg}</svg>` : ''; }
